const recoverQueuedHostingOperations = `-- name: RecoverQueuedHostingOperations :many
SELECT id FROM hosting_operations WHERE state='queued' AND run_id IS NULL ORDER BY updated_at,id LIMIT 100 FOR UPDATE SKIP LOCKED
`

func (q *Queries) RecoverQueuedHostingOperations(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, recoverQueuedHostingOperations)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

